function hasAllFields(entry) {
  return Boolean(entry.owner) && Boolean(entry.reason) && Boolean(entry.revisitBy);
}

function isOverdue(revisitBy, today) {
  return revisitBy < today;
}

function splitByQuarantine(ids, quarantinedIds) {
  const blocking = ids.filter((id) => !quarantinedIds.includes(id));
  const nonBlocking = ids.filter((id) => quarantinedIds.includes(id));
  return { blocking, nonBlocking };
}

function shardFor(testIndex, shardCount) {
  return testIndex % shardCount;
}

function workPerShard(totalMinutes, shards) {
  return totalMinutes / shards;
}

function countQuarantined(ids, quarantinedIds) {
  return ids.filter((id) => quarantinedIds.includes(id)).length;
}

function overdueIds(entries, today) {
  return entries.filter((e) => e.revisitBy < today).map((e) => e.testId);
}

function routeTests(allIds, entries) {
  const quarantined = new Set(entries.map((e) => e.testId));
  const blocking = allIds.filter((id) => !quarantined.has(id));
  const nonBlocking = allIds.filter((id) => quarantined.has(id));
  return { blocking, nonBlocking };
}
